require_admin($pdo);

$operatingTimeOptions = [];
for ($minute = 0; $minute < 1440; $minute += 30) $operatingTimeOptions[] = date('h:i A', mktime(0, $minute));
function branchManagementScheduleTimes(string $schedule): array {
    preg_match_all('/\b(\d{1,2}:\d{2}\s*(?:AM|PM))\b/i', $schedule, $matches);
    if (count($matches[1]) < 2) return ['09:00 AM', '05:00 PM'];
    return [strtoupper(date('h:i A', strtotime($matches[1][0]))), strtoupper(date('h:i A', strtotime(end($matches[1]))))];
}
function branchManagementPsgcCodes(PDO $pdo, array $branch): array {
    $query=$pdo->prepare('SELECT COALESCE(l.region_code,p.region_code) AS region_code,COALESCE(p.psgc_code,l.region_code) AS province_code,l.psgc_code AS municipality_code,b.psgc_code AS barangay_code FROM psgc_barangays b JOIN psgc_localities l ON l.psgc_code=b.locality_code LEFT JOIN psgc_provinces p ON p.psgc_code=l.province_code WHERE b.psgc_code=?');
    $query->execute([(string)($branch['barangay_code']??'')]);
    return $query->fetch(PDO::FETCH_ASSOC) ?: [];
}

$messages = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_admin($pdo);
    if (!csrf_check($_POST['csrf'] ?? null)) {
        $messages[] = ['kind'=>'danger','text'=>'Session expired. Refresh and try again.'];
    } else {
        $action = (string)($_POST['action'] ?? '');
        $id = filter_var($_POST['branch_id'] ?? 0, FILTER_VALIDATE_INT) ?: 0;
        if ($action === 'save') {
            $name = trim((string)($_POST['name'] ?? ''));
            $address = trim((string)($_POST['address'] ?? ''));
            $regionCode = trim((string)($_POST['province_code'] ?? ''));
            =->prepare('SELECT region_code FROM psgc_provinces WHERE psgc_code=?');
            ->execute([]);
            =(string)(->fetchColumn() ?: );
            $municipalityCode = trim((string)($_POST['municipality_code'] ?? ''));
            $barangayCode = trim((string)($_POST['barangay_code'] ?? ''));
            $place = psgc_resolve($pdo, $regionCode, $municipalityCode, $barangayCode);
            $city = (string)($place['municipality'] ?? '');
            $region = (string)($place['region'] ?? '');
            $zipCode = trim((string)($_POST['zip_code'] ?? ''));
            $lat = filter_var($_POST['latitude'] ?? null, FILTER_VALIDATE_FLOAT);
            $lng = filter_var($_POST['longitude'] ?? null, FILTER_VALIDATE_FLOAT);
            $phone = trim((string)($_POST['phone'] ?? ''));
            $openingTime = trim((string)($_POST['opening_time'] ?? ''));
            $closingTime = trim((string)($_POST['closing_time'] ?? ''));
            $phoneValid = preg_match('/^\d{7,15}$/', $phone) === 1;
            $openingMinutes = DateTimeImmutable::createFromFormat('!h:i A', $openingTime);
            $closingMinutes = DateTimeImmutable::createFromFormat('!h:i A', $closingTime);
            $scheduleValid = in_array($openingTime, $operatingTimeOptions, true) && in_array($closingTime, $operatingTimeOptions, true)
                && $openingMinutes && $closingMinutes && $closingMinutes > $openingMinutes;
            $schedule = $scheduleValid ? $openingTime . ' – ' . $closingTime : '';
            $archivedEdit=false;
            if($id){$check=$pdo->prepare("SELECT status FROM branches WHERE branch_id=?");$check->execute([$id]);$archivedEdit=$check->fetchColumn()==='archived';}
            if ($archivedEdit) {
                $messages[]=['kind'=>'danger','text'=>'Restore this archived branch before editing its details.'];
            } elseif ($name === '' || mb_strlen($name) > 160 || $address === '' || mb_strlen($address) > 255 || !preg_match('/^\d{4}$/',$zipCode) || !$place || $lat === false || $lng === false || !branch_is_within_philippines((float)$lat, (float)$lng) || !$phoneValid || !$scheduleValid) {
                $messages[] = ['kind'=>'danger','text'=>'Enter all branch details, a digits-only phone number, valid opening and closing times with closing later than opening, and place a map pin inside the Philippines.'];
            } else {
                try {
                    if ($id) {
                        $beforeQuery=$pdo->prepare('SELECT name,street_address,barangay_code,zip_code,latitude,longitude,phone,schedule,supports_delivery,supports_pickup,status FROM branches WHERE branch_id=?');
                        $beforeQuery->execute([$id]);
                        $beforeBranch=$beforeQuery->fetch(PDO::FETCH_ASSOC);
                        if (!$beforeBranch) throw new RuntimeException('Branch not found.');
                        $pdo->beginTransaction();
                        $stmt = $pdo->prepare('UPDATE branches SET name=?,street_address=?,barangay_code=?,zip_code=?,latitude=?,longitude=?,phone=?,schedule=?,supports_delivery=?,supports_pickup=? WHERE branch_id=?');
                        $stmt->execute([$name,$address,$place['barangay_code'],$zipCode,$lat,$lng,$phone,$schedule,isset($_POST['supports_delivery'])?1:0,isset($_POST['supports_pickup'])?1:0,$id]);
                        write_audit_log($pdo,'branch_details_updated','branch',(int)$id,$beforeBranch,['name'=>$name,'street_address'=>$address,'barangay_code'=>$place['barangay_code'],'zip_code'=>$zipCode,'latitude'=>(float)$lat,'longitude'=>(float)$lng,'phone'=>$phone,'schedule'=>$schedule,'supports_delivery'=>isset($_POST['supports_delivery'])?1:0,'supports_pickup'=>isset($_POST['supports_pickup'])?1:0,'status'=>$beforeBranch['status']]);
                        $pdo->commit();
                        $messages[] = ['kind'=>'success','text'=>'Branch details updated.'];
                    } else {
                        $pdo->beginTransaction();
                        $pdo->prepare("INSERT INTO branches(name,street_address,barangay_code,zip_code,latitude,longitude,phone,schedule,supports_delivery,supports_pickup,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)")
                            ->execute([$name,$address,$place['barangay_code'],$zipCode,$lat,$lng,$phone,$schedule,isset($_POST['supports_delivery'])?1:0,isset($_POST['supports_pickup'])?1:0,(int)$_SESSION['user_id']]);
                        $newId = (int)$pdo->lastInsertId();
                        $pdo->prepare("INSERT INTO team_inbox_events(event_type,title,message,audience,entity_type,entity_id,created_by) VALUES('branch_added',?,?, 'all','branch',?,?)")
                            ->execute(['New branch: '.$name,$name.' is now open in '.$city.', '.$region.'.',$newId,(int)$_SESSION['user_id']]);
                        write_audit_log($pdo,'branch_created','branch',$newId,null,['name'=>$name,'street_address'=>$address,'barangay_code'=>$place['barangay_code'],'zip_code'=>$zipCode,'latitude'=>(float)$lat,'longitude'=>(float)$lng,'phone'=>$phone,'schedule'=>$schedule,'supports_delivery'=>isset($_POST['supports_delivery'])?1:0,'supports_pickup'=>isset($_POST['supports_pickup'])?1:0,'status'=>'open']);
                        $pdo->commit();
                        try { notify_nomcha_users('branch_notification','A new Nomcha branch is open',$name.' is now open at '.$address.', '.$city.', '.$region.'. Find details and directions on our branch page.','branches.php'); }
                        catch (Throwable $mailError) { error_log('Branch notification failed: '.$mailError->getMessage()); }
                        $messages[] = ['kind'=>'success','text'=>'Branch added. A dashboard news item was created and subscriber notices were sent where delivery was available.'];
                    }
                } catch (Throwable $error) {
                    if ($pdo->inTransaction()) $pdo->rollBack();
                    $messages[] = ['kind'=>'danger','text'=>'Could not save the branch. Apply the branch management migration and try again.'];
                }
            }
        } elseif ($action === 'status' && $id) {
            $status = (string)($_POST['status'] ?? '');
            $current=$pdo->prepare('SELECT status,name FROM branches WHERE branch_id=?'); $current->execute([$id]); $currentBranch=$current->fetch(PDO::FETCH_ASSOC); $currentStatus=$currentBranch['status']??false;
            if (!$currentStatus || !in_array($status,['open','closed','archived'],true) || ($currentStatus==='archived' && $status!=='open')) $messages[]=['kind'=>'danger','text'=>'Choose a valid branch status.'];
            else {
                $pdo->beginTransaction();
                try {
                $update=$pdo->prepare('UPDATE branches SET status=? WHERE branch_id=?');
                $update->execute([$status,$id]);
                write_audit_log($pdo,'branch_status_changed','branch',(int)$id,['status'=>$currentStatus,'name'=>$currentBranch['name']],['status'=>$status,'name'=>$currentBranch['name']]);
                $pdo->commit();
                if ($update->rowCount() === 0 && $currentStatus !== $status) {
                    $messages[]=['kind'=>'danger','text'=>'Branch status could not be updated. Please try again.'];
                } else {
                    $messages[]=['kind'=>'success','text'=>$status==='archived'?'Branch archived and removed from public maps.':($status==='closed'?'Branch marked closed.':'Branch reopened.')];
                }
                } catch(Throwable $error) { if($pdo->inTransaction())$pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Branch status could not be updated. Please try again.']; }
            }
        }
    }
}
$branchSelect="SELECT b.*,b.street_address AS address,l.name AS city,COALESCE(p.name,r.name) AS province,r.name AS region FROM branches b JOIN psgc_barangays ba ON ba.psgc_code=b.barangay_code JOIN psgc_localities l ON l.psgc_code=ba.locality_code LEFT JOIN psgc_provinces p ON p.psgc_code=l.province_code JOIN psgc_regions r ON r.psgc_code=COALESCE(l.region_code,p.region_code)";
$branches = $pdo->query($branchSelect." WHERE b.status<>'archived' ORDER BY FIELD(b.status,'open','closed'),b.name")->fetchAll(PDO::FETCH_ASSOC);
$archivedBranches = $pdo->query($branchSelect." WHERE b.status='archived' ORDER BY b.name")->fetchAll(PDO::FETCH_ASSOC);
$assigned = [];
$newBranchPsgc=psgc_form_state($pdo,[]);
$staffQuery = $pdo->query("SELECT bs.branch_id,i.first_name,i.last_name FROM branch_staff bs JOIN user_credentials c ON c.user_id=bs.user_id JOIN user_info i ON i.user_id=c.user_id WHERE c.role='staff' AND c.is_active=1 ORDER BY i.last_name,i.first_name");
foreach ($staffQuery->fetchAll(PDO::FETCH_ASSOC) as $person) $assigned[(int)$person['branch_id']][] = trim($person['first_name'].' '.$person['last_name']);
$pageTitle='Branch management';
$pageStyles='<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css">';
$pageScripts='<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script><script src="assets/js/psgc-select.js?v=' . filemtime(__DIR__ . '/assets/js/psgc-select.js') . '"></script>';
require 'includes/header.php'; render_toasts($messages);
?>
