<script>
document.addEventListener('DOMContentLoaded',()=>{const branches=JSON.parse(document.getElementById('management-branch-data').textContent||'[]');const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const bounds=L.latLngBounds([[4.5,116.9],[21.2,126.7]]);const makeMap=id=>{const map=L.map(id,{maxBounds:bounds,maxBoundsViscosity:1,minZoom:5}).setView([14.6,121.0],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);return map;};const maps=[makeMap('management-branch-map')];document.querySelectorAll('.branch-pin-map').forEach((element,index)=>{element.id='branch-pin-map-'+index;const form=element.closest('form'),lat=form.querySelector('[name=latitude]'),lng=form.querySelector('[name=longitude]'),pinMap=makeMap(element.id);let marker=null;const setPin=point=>{lat.value=point.lat.toFixed(6);lng.value=point.lng.toFixed(6);if(marker)marker.setLatLng(point);else marker=L.marker(point).addTo(pinMap);};if(lat.value&&lng.value){const point={lat:Number(lat.value),lng:Number(lng.value)};setPin(point);pinMap.setView(point,14);}pinMap.on('click',event=>{setPin(event.latlng);element.classList.remove('border','border-danger');});element._pinMap=pinMap;});document.querySelectorAll('details').forEach(details=>details.addEventListener('toggle',()=>{if(details.open)details.querySelector('.branch-pin-map')?._pinMap?.invalidateSize();}));let layers=[];const color={open:'#198754',closed:'#d28a00',archived:'#6c757d'};const markerIcon=status=>L.divIcon({className:'branch-map-marker',html:`<span style="background:${color[status]||color.archived}"></span>`,iconSize:[22,22],iconAnchor:[11,11]});const render=()=>{const status=document.getElementById('branch-map-status-filter').value,term=document.getElementById('branch-map-search').value.trim().toLowerCase();const visible=branches.filter(b=>(!status||b.status===status)&&(!term||`${b.name} ${b.address} ${b.status}`.toLowerCase().includes(term)));const listStatus=document.getElementById('branch-list-status').value,listTerm=document.getElementById('branch-list-search').value.trim().toLowerCase();const listCards=[...document.querySelectorAll('[data-branch-card]')];let listVisible=0;listCards.forEach(card=>{const match=(!listStatus||card.dataset.status===listStatus)&&(!listTerm||card.dataset.search.includes(listTerm));card.hidden=!match;if(match)listVisible++;});document.getElementById('branch-list-count').textContent=listVisible+' of '+listCards.length+' branches';document.getElementById('branch-map-count').textContent=`${visible.length} of ${branches.length} branches`;document.querySelectorAll('[data-map-filter]').forEach(el=>el.value=status);document.querySelectorAll('[data-map-search]').forEach(el=>el.value=document.getElementById('branch-map-search').value);document.querySelectorAll('[data-map-count]').forEach(el=>el.textContent=`${visible.length} of ${branches.length} branches`);layers.forEach(layer=>maps.forEach(map=>map.removeLayer(layer)));layers=[];maps.forEach(map=>{const layer=typeof L.markerClusterGroup==='function'?L.markerClusterGroup({disableClusteringAtZoom:14}):L.layerGroup();layers.push(layer);visible.forEach(b=>L.marker([b.lat,b.lng],{icon:markerIcon(b.status)}).bindPopup(`<strong>${esc(b.name)}</strong><br>${esc(b.address)}<br><span class="map-status map-status-${b.status}">${esc(b.status.toUpperCase())}</span>`).addTo(layer));layer.addTo(map);if(visible.length)map.fitBounds(L.latLngBounds(visible.map(b=>[b.lat,b.lng])),{padding:[24,24],maxZoom:8});});};render();document.getElementById('branch-map-status-filter').addEventListener('change',render);document.getElementById('branch-map-search').addEventListener('input',render); document.getElementById('branch-list-status').addEventListener('change',render);document.getElementById('branch-list-search').addEventListener('input',render);document.getElementById('branch-list-filter-reset').addEventListener('click',()=>{document.getElementById('branch-list-status').value='';document.getElementById('branch-list-search').value='';render();});document.querySelectorAll('[data-map-filter]').forEach(el=>el.addEventListener('change',()=>{document.getElementById('branch-map-status-filter').value=el.value;render();}));document.querySelectorAll('[data-map-search]').forEach(el=>el.addEventListener('input',()=>{document.getElementById('branch-map-search').value=el.value;render();}));document.querySelectorAll('[data-branch-focus]').forEach(el=>{const focus=()=>{const b=branches.find(b=>String(b.id)===el.dataset.branchFocus);if(!b)return;document.getElementById('branch-map-status-filter').value='';document.getElementById('branch-map-search').value='';render();maps[0].setView([b.lat,b.lng],14,{animate:false});layers[0].eachLayer(marker=>{if(marker.getLatLng().lat===b.lat&&marker.getLatLng().lng===b.lng)marker.openPopup();});};el.addEventListener('click',focus);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();focus();}});});document.getElementById('branchMapModal').addEventListener('shown.bs.modal',()=>{maps[1]??=makeMap('management-branch-map-expanded');render();maps[1].invalidateSize();});window.addEventListener('resize',()=>maps.forEach(m=>m.invalidateSize()));const modal=new bootstrap.Modal(document.getElementById('managementConfirmModal'));let pending=null;document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{if(form.dataset.confirmed==='1'){form.dataset.confirmed='';return;}const action=form.querySelector('[name="action"]')?.value;if(action==='save'){const lat=form.querySelector('[name=latitude]'),lng=form.querySelector('[name=longitude]'),opening=form.querySelector('[name=opening_time]'),closing=form.querySelector('[name=closing_time]');if(!lat.value||!lng.value){event.preventDefault();form.querySelector('.branch-pin-map').scrollIntoView({behavior:'smooth',block:'center'});form.querySelector('.branch-pin-map').classList.add('border','border-danger');return;}const toMinutes=value=>{const match=value.match(/^(\d{2}):(\d{2}) (AM|PM)$/);if(!match)return null;return ((Number(match[1])%12)+(match[3]==='PM'?12:0))*60+Number(match[2]);};const startMinutes=toMinutes(opening.value),endMinutes=toMinutes(closing.value);closing.setCustomValidity(startMinutes!==null&&endMinutes!==null&&startMinutes<endMinutes?'':'Closing time must be later than opening time.');if(!form.reportValidity()){event.preventDefault();return;}}event.preventDefault();pending=form;const status=form.querySelector('[name="status"]')?.value;document.getElementById('managementConfirmTitle').textContent='Confirm update';document.getElementById('managementConfirmMessage').textContent=action==='status'?(`Change this branch status to ${status==='archived'?'Archived':status}?`):action==='save'?(form.querySelector('[name="branch_id"]')?'Save these branch details?':'Add this branch and notify subscribers?'):action==='assign'?'Save these staff assignments?':'Continue with this update?';modal.show();}));document.getElementById('managementConfirmSubmit').addEventListener('click',()=>{if(pending){const form=pending;pending=null;form.dataset.confirmed='1';modal.hide();form.requestSubmit();}});});
</script>
