.branch-pin-map{height:280px;min-height:240px;border:1px solid #ced4da;border-radius:.5rem;overflow:hidden}.management-map{height:420px;min-height:320px;position:relative;z-index:0}
.management-map-expanded{flex:1;min-height:0;border-radius:.5rem;overflow:hidden;background:#e6e1d8}
