.status-open{background:#198754;color:#fff}.status-closed{background:#ffc107;color:#332600}.status-archived{background:#6c757d;color:#fff}
.branch-map-marker{background:transparent;border:0}
.branch-map-marker span{display:block;width:20px;height:20px;border:3px solid #fff;border-radius:50%;box-shadow:0 1px 5px #2228}
.map-status{display:inline-block;margin-top:.25rem;padding:.2rem .45rem;border-radius:1rem;color:white;font-size:.7rem;font-weight:700;letter-spacing:.04em}.map-status-open{background:#198754}.map-status-closed{background:#a96800}.map-status-archived{background:#6c757d}
</style>
